    SELECT SEQ_ACTIVITY_NO.NEXTVAL FROM DUAL


INSERT
  INTO
       CL_ACTIVITY_BOARD
       (
       ACTIVITY_NO
     , ACTIVITY_TITLE
     , ACTIVITY_CONTENT
     , LAT
     , LNG
     , VIEW_COUNT
     , STATUS
     , ENROLL_DATE
     , MEMBER_NO
     , REGION_NO
     , ADDRESS
       )
VALUES
       (
       #{activityNo}
     , #{title}
     , #{content}
     , #{lat}
     , #{lng}
     , DEFAULT
     , 'Y'
     , SYSDATE
     , #{memberNo}
     , #{regionNo}
     , #{address}
       )

INSERT 
  INTO 
       CL_ACTIVITY_CERTIFICATION 
       (
       ACTIVITY_BOARD_NO
     , CERTIFICATION_NO
       ) 
VALUES 
       (
       #{activityNo}
     , #{certificationNo}
       )

mapper.update:
UPDATE
       CL_ACTIVITY_REPLY
   SET
       REPLY_CONTENT = #{replyContent}
 WHERE
       REPLY_NO = #{replyNo}
   AND
       MEMBER_NO = #{memberNo}
   AND
       STATUS = 'Y'

UPDATE
       CL_ACTIVITY_BOARD
   SET
       ACTIVITY_TITLE = #{title}
     , ACTIVITY_CONTENT = #{content}
     , ADDRESS = #{address}
     , LAT = #{lat}
     , LNG = #{lng}
     , REGION_NO = #{regionNo}
 WHERE
       ACTIVITY_NO = #{activityNo}

UPDATE
       CL_ACTIVITY_CERTIFICATION
   SET
       CERTIFICATION_NO = #{certificationNo}
 WHERE
       ACTIVITY_BOARD_NO = #{activityNo}
